/// <reference types="vite/client" />

/**
 * Stamped in by `vite.config.ts` at build time.
 *
 * Not read from `package.json` at runtime: a packaged app has no package.json,
 * and the build TIME is the half that actually answers "am I running the build
 * with the fix in it".
 */
declare const __APP_VERSION__: string;
declare const __BUILD_TIME__: string;
